# C.-F. Volney, Tableau du climat et du sol des États-Unis d'Amérique, suivi d'éclaircissements sur la Floride, sur la colonie
# française au Scioto, sur quelques colonies canadiennes et sur les sauvages, Paris, 1803 (éd. des Œuvres, t. IV, Project
# Gutenberg ; epub du Drive de l'auteur, pack « Histoire des États-Unis »). Voyage de l'été 1796. Préfixe VO03.
from commun import Corpus
VO = "Volney, Constantin-François (1803), Tableau du climat et du sol des États-Unis d'Amérique, Paris (éd. Œuvres, t. IV, Project Gutenberg)"
C = Corpus('Recherches', 'VO03', VO, page_fmt='{}')
F = C.F
V = 'Constantin-François Volney'
F('01', "Gallipolis : Volney chez les Français du Scioto (11 juillet 1796)", 'etablissement', '1790/1796-07-11', -82.2022, 38.8098, 'c', [V, 'Rufus Putnam'],
  "Arrivé de nuit à Gallipolis le 11 juillet 1796, Volney trouve deux rangs de cabanes de rondins blanchies sur la berge de l'Ohio et des colons hâves, minés chaque automne par les fièvres. Environ cinq cents Français, artisans et bourgeois, avaient acheté en 1790 à la compagnie du Scioto des terres à six livres l'acre et débarqué en 1791-1792 ; la compagnie fit faillite, la compagnie de l'Ohio refusa de reconnaître leurs titres, et les Indiens vainqueurs de Saint-Clair (1791) bloquèrent le village en 1792-1793. La plupart se dispersèrent ; les restants rachetèrent 912 acres et le Congrès donna en 1795 vingt mille acres face au ruisseau Sandy (le French Grant) à quatre-vingt-deux ou quatre-vingt-quatre survivants.",
  "art. III", "Point à Gallipolis (Ohio).")
F('02', "Poste-Vincennes : « un français passable, mêlé de termes de soldat » (2-12 août 1796)", 'etablissement', '1796-08-02/1796-08-12', -87.5286, 38.6773, 'c', [V],
  "Arrivé le 2 août 1796 après trois jours de cheval depuis Louisville, Volney décrit un village d'une cinquantaine de maisons blanches, chacune isolée dans sa cour palissadée « selon la bonne coutume canadienne », et un petit fort de pieux. À l'audience des juges, il distingue les colons américains, bien portants, des Français établis depuis une soixantaine d'années, maigres et pauvres : pillés par une troupe kentuckienne vers 1782, ruinés par la guerre indienne de 1788, ils ont vendu à vil prix les 400 arpents donnés par le Congrès en 1792. Sur quatre-vingt-dix Français, à peine six savent lire ; il n'y avait jamais eu d'école avant l'arrivée d'un abbé émigré. Leur langue n'est pas un patois, juge-t-il, mais un français passable ; il situe la fondation vers 1735.",
  "art. IV", "Point au vieux Vincennes (Indiana). L'abbé « R… » est sans doute Jean-François Rivet, missionnaire à Vincennes à partir de 1795.")
F('03', "Kaskaskia : « pas douze familles canadiennes » (1796)", 'etablissement', '1796', -89.9137, 37.9225, 'a', [V],
  "D'après les témoins qui en reviennent, Volney rapporte que Kaskaskia, en vallée très chaude, est si ruiné qu'il n'y reste pas douze familles canadiennes, alors que le colonel Bouquet y comptait quatre cents personnes en 1764 ; le village entier appartient presque à une seule maison américaine (« E… »). On y avait moissonné le 1er juillet. La prairie qui le sépare de Vincennes, à quarante-trois heures de marche, a perdu ses troupeaux de bisons, partis à la nage au-delà du Mississippi.",
  "art. IV et Tableau, ch. sur le climat", "Volney n'a pas dépassé Vincennes : informations de seconde main. La maison « E… » est vraisemblablement celle de John Edgar. Point à l'ancien Kaskaskia, emporté depuis par le Mississippi.")
F('04', "Sainte-Geneviève, fort de Chartres et Nouvelle-Madrid : le fleuve « très mauvais voisin » (1796)", 'evenement', '1796', -90.05, 37.98, 'a', [V],
  "Volney note que le Mississippi a balayé l'ancien village de Sainte-Geneviève, dont les habitants vivent désormais à deux milles de là, sur les hauteurs, dans des maisons à pans de bois ; qu'il a renversé le fort de Chartres, bâti « avec une magnificence extraordinaire », cinq lieues au-dessus de Kaskaskia ; et qu'il mine déjà un bastion de la Nouvelle-Madrid, fondée en 1791 en face de l'embouchure de l'Ohio.",
  "art. IV", "Point à Sainte-Geneviève (Missouri) ; informations de seconde main.")
F('05', "Cahokia et Prairie du Rocher : des villages qui se vident (1796)", 'etablissement', '1790/1796', -90.1893, 38.5709, 'a', [V, 'Winthrop Sargent'],
  "Cahokia n'a plus que quarante feux, au lieu de quatre-vingts en 1790, et la Prairie du Rocher dix familles, sur des rives chaudes et fiévreuses. Selon le colonel Winthrop Sargent, secrétaire du Territoire du Nord-Ouest, qui inspecta en 1790 les établissements de la rive gauche, l'ensemble des familles françaises n'y dépassait pas cent cinquante. Les Américains rachètent les terres des anciens colons, qui partent pour la Louisiane ou le Canada.",
  "art. IV", "Point à Cahokia (Illinois).")
F('06', "Saint-Louis, dit « Pancore » : soixante-dix maisons et cinq cents Blancs (1796)", 'etablissement', '1796', -90.1857, 38.6270, 'a', [V],
  "En face de Cahokia, Saint-Louis, que l'on surnomme Pancore, n'est selon les informateurs de Volney qu'un bourg de soixante-dix maisons groupées, avec un beau fort de pierre de deux acres, cinq ou six familles riches qui possèdent le peu d'esclaves noirs, et cinq cents Blancs pauvres et fiévreux. La milice de toute la Haute-Louisiane ne dépasse pas sept cents hommes, soit au plus deux mille cinq cents Français. Deux de ses compagnons kentuckiens partent s'établir au Missouri, où l'Espagne concède des terres aux Américains qui se naturalisent : plus de huit cents y sont déjà.",
  "art. IV", "Point dans la vieille ville de Saint-Louis ; informations de seconde main (Volney renonce à s'y rendre).")
fiches = C.fiches
